try { new Function('X', 'applyMacros', "/* 🌱 一起养一个小生命：一盆花或一只小猫；你们聊得越多长得越好，你能浇水/喂它，TA 也会自己去照顾还跟你汇报 */\nif (window.__gyxPet2) return; window.__gyxPet2 = 1;\nX.feat('gyxGrow', { n: '🌱 一起养小生命', desc: '花、多肉、向日葵、小树、猫、狗、兔子、仓鼠、鱼、鸟、乌龟，或者你自己定一种；聊得越多长得越好，TA 也会去照顾它' });\nconst S = X.store('grow');\nlet D = { list: [], custom: {} };   // custom：你自己定的种类 {id:{n,e,type,stages,need,act,icon}}   // {id, kind:'plant'|'cat', name, cid, born, exp, water(0-100), love(0-100), last, log:[], chatSeen}\n// 种类：花和猫是原来的；后面是新加的。你也可以自己定一种（D.custom 里），type 决定它是「植物」还是「小动物」\nconst KINDS = {\n    plant: { n: '一盆花', e: '🌷', type: 'plant', stages: ['🌰 种子', '🌱 发芽', '🌿 长叶子', '🪴 抽枝', '🌷 开花', '💐 满盆花'], need: '浇水', act: '浇了水', icon: '💧', col: '#ff8fb1' },\n    cat: { n: '一只小猫', e: '🐱', type: 'animal', stages: ['🥚 刚捡回来', '🐱 小奶猫', '🐈 小猫', '😺 半大猫', '🐈‍⬛ 大猫', '👑 猫主子'], need: '喂猫粮', act: '喂了猫粮', icon: '🐟' },\n    dog: { n: '一只小狗', e: '🐶', type: 'animal', stages: ['📦 刚抱回来', '🐶 小奶狗', '🐕 小狗', '🦮 会握手了', '🐕‍🦺 大狗', '👑 狗狗队长'], need: '喂狗粮', act: '喂了狗粮', icon: '🦴', pat: '🤚 揉揉头' },\n    bunny: { n: '一只兔子', e: '🐰', type: 'animal', stages: ['🧺 刚接回家', '🐰 小毛球', '🐇 会蹦了', '🥕 爱吃胡萝卜', '🐇 大兔子', '🌙 月亮上那只'], need: '喂胡萝卜', act: '喂了胡萝卜', icon: '🥕' },\n    hamster: { n: '一只仓鼠', e: '🐹', type: 'animal', stages: ['🥜 一小团', '🐹 小仓鼠', '🎡 会跑轮子了', '🌻 囤了一嘴瓜子', '🐹 圆滚滚', '👑 仓鼠大王'], need: '喂瓜子', act: '喂了瓜子', icon: '🌻' },\n    fish: { n: '一缸小鱼', e: '🐠', type: 'animal', stages: ['🫧 鱼苗', '🐟 小鱼', '🐠 花小鱼', '🐡 会吐泡泡了', '🐠 大鱼', '🐉 鱼跃龙门'], need: '撒鱼食', act: '撒了鱼食', icon: '🫧', pat: '👆 敲敲鱼缸' },\n    bird: { n: '一只小鸟', e: '🐦', type: 'animal', stages: ['🥚 蛋', '🐣 破壳', '🐥 小黄鸟', '🐦 会唱歌了', '🦜 会学舌了', '🕊️ 会飞回来找你们'], need: '喂小米', act: '喂了小米', icon: '🌾', pat: '🎵 吹口哨给它听' },\n    turtle: { n: '一只小乌龟', e: '🐢', type: 'animal', stages: ['🥚 龟蛋', '🐢 硬币那么大', '🐢 巴掌大', '🪨 会晒背了', '🐢 慢慢变大', '🏆 活到一百岁'], need: '喂龟粮', act: '喂了龟粮', icon: '🦐' },\n    cactus: { n: '一盆多肉', e: '🌵', type: 'plant', stages: ['🌰 叶插', '🌱 冒小芽', '🪴 胖了一圈', '🌵 长成一丛', '🌸 开花了', '🪷 爆盆'], need: '浇一点点水', act: '浇了一点点水', icon: '💧', col: '#ffb4d0' },\n    sun: { n: '一棵向日葵', e: '🌻', type: 'plant', stages: ['🌰 瓜子', '🌱 发芽', '🌿 长高', '🪴 比窗台还高', '🌻 开花', '🌻 结了一盘瓜子'], need: '浇水', act: '浇了水', icon: '💧', col: '#ffcc33' },\n    tree: { n: '一棵小树', e: '🌳', type: 'plant', stages: ['🌰 树种', '🌱 小苗', '🌿 小树枝', '🌳 小树', '🍎 结果子了', '🌳 能乘凉了'], need: '浇水', act: '浇了水', icon: '💧', col: '#ff6b6b' }\n};\nconst KK = k => KINDS[k] || (D.custom && D.custom[k]) || KINDS.plant;\nconst isAni = p => KK(p.kind).type === 'animal';\nconst STEP = [0, 30, 90, 200, 380, 650];\nconst stage = p => { let s = 0; STEP.forEach((v, i) => { if (p.exp >= v) s = i; }); return s; };\nfunction decay(p) {   // 时间流逝：水/饱慢慢掉，一天大约掉 40\n    const h = (Date.now() - (p.last || Date.now())) / 3600000; if (h <= 0) return;\n    p.water = Math.max(0, p.water - h * 1.7); p.love = Math.max(0, p.love - h * 0.8); p.last = Date.now();\n}\nconst mood = p => p.water < 20 ? (!isAni(p) ? '有点蔫了' : p.kind === 'cat' ? '饿得喵喵叫' : '饿了，眼巴巴看着你们') : p.love < 25 ? '想你们陪陪它' : p.water > 70 && p.love > 60 ? '状态超好' : '还不错';\nfunction log(p, t) { p.log.unshift({ t, at: Date.now() }); if (p.log.length > 200) p.log.length = 200; }\n// 你们聊天：每天有新消息就长一点（每 5 条 +1）\nfunction chatGrow() { if (!X.on('gyxGrow')) return;\n    let ch = false;\n    D.list.forEach(p => { const H = (typeof globalChats !== 'undefined' && globalChats[p.cid]) || []; const n = H.filter(m => m.sender !== 'system').length; if (p.chatSeen == null) { p.chatSeen = n; ch = true; return; } if (n - p.chatSeen >= 5) { const g = Math.floor((n - p.chatSeen) / 5); p.exp += g; p.love = Math.min(100, p.love + g * 2); p.chatSeen += g * 5; ch = true; } });\n    if (ch) S.set('d', D);\n}\nwindow.gyxGrowCare = async function (id, who) {\n    const p = D.list.find(x => x.id === id); if (!p) return; decay(p);\n    const K = KK(p.kind), s0 = stage(p);\n    if (who === 'me') { p.water = Math.min(100, p.water + 35); p.love = Math.min(100, p.love + 8); p.exp += 3; log(p, `你${K.act}`); }\n    else if (who === 'pat') { p.love = Math.min(100, p.love + 15); p.exp += 1; log(p, p.kind === 'cat' ? '你摸了摸它，它呼噜呼噜' : isAni(p) ? `你${(KK(p.kind).pat || '🤚 摸摸').replace(/^\\S+\\s/, '')}，它很开心` : '你跟它说了会儿话'); }\n    await S.set('d', D);\n    if (stage(p) > s0) { const c = X.char(p.cid); X.toast(`${K.stages[stage(p)]}！`, `${p.name} 长大了`); X.say(c, await report(p, 'grow')); }\n    paint();\n};\nasync function report(p, why) {\n    const c = X.char(p.cid), K = KK(p.kind);\n    if (X.bailu()) return X.cards(['养成', '聊天'], c, 1)[0] || (why === 'grow' ? `${p.name}${K.stages[stage(p)].slice(2)}了！` : `我刚给${p.name}${K.act}。`);\n    const t = await X.ask(`${X.who(c)}\\n你们一起养了${K.n}，叫「${p.name}」，现在是「${K.stages[stage(p)]}」阶段，状态：${mood(p)}。\\n${why === 'grow' ? '它刚刚长大了一个阶段！' : why === 'care' ? '你刚刚自己去' + K.act + '，顺便看了看它。' : '你想跟她说说它的近况。'}跟她说一句（口语，不超过 50 字，可以带点细节）。只输出这句话。`);\n    return t ? X.plain(t) : `我刚去看了看${p.name}。`;\n}\n// TA 自己去照顾：默认模式的 TA 每天随机一次；自主模式的 TA 自己决定（在行动菜单里）\nasync function taCare(p) {\n    const c = X.char(p.cid); if (!c) return null; decay(p);\n    p.water = Math.min(100, p.water + 35); p.exp += 2; log(p, `${X.name(c)} ${KK(p.kind).act}`); p.taDay = X.day();\n    await S.set('d', D);\n    const t = await report(p, 'care'); X.say(c, t); return t;\n}\nwindow.gyxGrowTaCare = id => taCare(D.list.find(x => x.id === id));\nX.action({ key: 'gyx_grow', label: '去照顾你们一起养的小生命', hint: '浇水 / 喂它，顺便跟她汇报', need: c => D.list.some(p => p.cid === String(c.id) && p.taDay !== X.day()), run: async c => { const p = D.list.find(x => x.cid === String(c.id) && x.taDay !== X.day()); return p && (await taCare(p)) ? `照顾了${p.name}` : null; } }, 'gyxGrow');\nasync function tick() { if (!X.on('gyxGrow')) return;\n    chatGrow();\n    for (const p of D.list) { decay(p); const c = X.char(p.cid); if (!c || X.auto(c) || p.taDay === X.day()) continue; const h = new Date().getHours(); if (h >= 9 && h <= 22 && Math.random() < 0.15) await taCare(p); }\n    await S.set('d', D); paint(); X.repaint();\n}\nwindow.gyxGrowNew = async function (kind, cid, name) {\n    const c = X.char(cid) || X.cur(); if (!c) return;\n    const K0 = KK(kind); const p = { id: 'g' + Date.now(), kind, name: name || (kind === 'cat' ? '团子' : KINDS[kind] ? X.pick(K0.type === 'animal' ? ['团子', '豆豆', '年糕', '布丁', '小满'] : ['小芽', '春春', '绿绿', '小满']) : (K0.e || '') + (K0.n || '').replace(/^一(只|盆|棵|缸|条|个)/, '')), cid: String(c.id), born: Date.now(), exp: 0, water: 70, love: 60, last: Date.now(), log: [], chatSeen: null };\n    log(p, `你和 ${X.name(c)} 一起${kind === 'cat' ? '捡回了一只小猫' : K0.type === 'animal' ? '把' + K0.n + '接回了家' : '种下了' + K0.n}`); D.list.push(p); await S.set('d', D);\n    X.say(c, kind === 'cat' ? `以后${p.name}就是我们的猫了。` : K0.type === 'animal' ? `以后${p.name}就是我们家的了。` : `种下了，我们一起等${p.name}长大。`);\n    window.gyxGrowOpen(); return p;\n};\nfunction art(p) {\n    const s = stage(p), sad = p.water < 20;\n    const K = KK(p.kind);\n    if (K.type === 'plant') {\n        const h = [8, 26, 48, 70, 88, 96][s], leaves = [0, 2, 4, 6, 8, 12][s], fl = s >= 4 ? (s === 5 ? 5 : 2) : 0;\n        let g = `<path d=\"M100 170 Q ${sad ? 110 : 100} ${170 - h / 2} ${sad ? 118 : 100} ${170 - h}\" stroke=\"#4f9a5b\" stroke-width=\"4\" fill=\"none\" stroke-linecap=\"round\"/>`;\n        for (let i = 0; i < leaves; i++) { const y = 165 - (i + 1) * h / (leaves + 1), sd = i % 2 ? 1 : -1; g += `<path d=\"M${100 + (sad ? i : 0)} ${y} q ${sd * 22} ${-8 + (sad ? 14 : 0)} ${sd * 30} ${4 + (sad ? 10 : 0)} q ${-sd * 14} 8 ${-sd * 30} -4 z\" fill=\"#7cc38a\"/>`; }\n        for (let i = 0; i < fl; i++) { const x = 100 + (i - (fl - 1) / 2) * 22, y = 170 - h - (i % 2) * 10; g += `<g transform=\"translate(${x} ${y})\">${[0, 72, 144, 216, 288].map(a => `<ellipse rx=\"7\" ry=\"11\" transform=\"rotate(${a}) translate(0 -9)\" fill=\"${K.col || '#ff8fb1'}\"/>`).join('')}<circle r=\"5\" fill=\"#ffd166\"/></g>`; }\n        if (s === 0) g = `<ellipse cx=\"100\" cy=\"164\" rx=\"9\" ry=\"6\" fill=\"#a47148\"/>`;\n        return `<svg viewBox=\"0 0 200 220\"><path d=\"M60 170 L140 170 L130 212 L70 212 Z\" fill=\"#d98b5f\"/><rect x=\"54\" y=\"162\" width=\"92\" height=\"12\" rx=\"4\" fill=\"#c7764a\"/>${g}</svg>`;\n    }\n    if (p.kind !== 'cat') {   // 别的小动物：用它这个阶段的表情画，越长越大；饿了会灰一点\n        const em = (K.stages[s] || '').split(' ')[0] || K.e || '🐾', z = [46, 58, 70, 82, 94, 104][s];\n        return `<svg viewBox=\"0 0 200 220\"><ellipse cx=\"100\" cy=\"200\" rx=\"${z * .55}\" ry=\"9\" fill=\"#0001\"/><text x=\"100\" y=\"${196 - z * .12}\" text-anchor=\"middle\" font-size=\"${z}\" style=\"${sad ? 'filter:grayscale(.6)' : ''}\" class=\"gr-bob\">${em}</text>${s >= 3 ? `<text x=\"${100 + z * .55}\" y=\"${120 - z * .3}\" font-size=\"20\">${sad ? '💧' : '✨'}</text>` : ''}</svg>`;\n    }\n    const sc = [0.5, 0.62, 0.74, 0.86, 1, 1.08][s], col = ['#f4e3c1', '#f2c38b', '#f2c38b', '#e8a86a', '#e8a86a', '#e0955a'][s];\n    if (s === 0) return `<svg viewBox=\"0 0 200 220\"><ellipse cx=\"100\" cy=\"190\" rx=\"60\" ry=\"10\" fill=\"#0001\"/><path d=\"M60 180 q40 -70 80 0 z\" fill=\"#d7b48a\"/><circle cx=\"92\" cy=\"160\" r=\"3\" fill=\"#333\"/><circle cx=\"108\" cy=\"160\" r=\"3\" fill=\"#333\"/><path d=\"M82 142 l6 -14 l8 12 M118 142 l-6 -14 l-8 12\" fill=\"#f2c38b\"/></svg>`;\n    return `<svg viewBox=\"0 0 200 220\"><ellipse cx=\"100\" cy=\"200\" rx=\"${60 * sc}\" ry=\"9\" fill=\"#0001\"/><g transform=\"translate(100 200) scale(${sc}) translate(-100 -200)\">\n        <path d=\"M150 170 q40 -10 30 -50\" stroke=\"${col}\" stroke-width=\"10\" fill=\"none\" stroke-linecap=\"round\" class=\"gr-tail\"/>\n        <ellipse cx=\"100\" cy=\"165\" rx=\"52\" ry=\"38\" fill=\"${col}\"/><circle cx=\"100\" cy=\"105\" r=\"40\" fill=\"${col}\"/>\n        <path d=\"M66 85 l-6 -34 l30 20 z M134 85 l6 -34 l-30 20 z\" fill=\"${col}\"/><path d=\"M70 80 l-3 -18 l14 10 z M130 80 l3 -18 l-14 10 z\" fill=\"#ffb3c1\"/>\n        ${sad ? '<path d=\"M82 104 q6 -4 12 0 M106 104 q6 -4 12 0\" stroke=\"#333\" stroke-width=\"3\" fill=\"none\"/>' : '<circle cx=\"86\" cy=\"104\" r=\"5\" fill=\"#333\"/><circle cx=\"114\" cy=\"104\" r=\"5\" fill=\"#333\"/>'}\n        <path d=\"M96 116 l4 4 l4 -4 z\" fill=\"#ff8fa3\"/><path d=\"M100 120 q-6 8 -12 4 M100 120 q6 8 12 4\" stroke=\"#333\" stroke-width=\"2\" fill=\"none\"/>\n        <path d=\"M70 118 l-24 -4 M70 124 l-24 4 M130 118 l24 -4 M130 124 l24 4\" stroke=\"#333\" stroke-width=\"1.5\"/></g></svg>`;\n}\nlet SEL = '';\nfunction paint() {\n    const b = document.getElementById('gyxGrBody'); if (!b) return;\n    if (!D.list.length) {\n        b.innerHTML = `<div class=\"gyx-tip\">和谁一起养？</div><div class=\"gyx-row\">${X.whoSel((X.cur() || {}).id, 'gyxGrowWho')}</div>\n        ${pickHtml()}`; return;\n    }\n    const p = D.list.find(x => x.id === SEL) || D.list[0]; SEL = p.id; decay(p);\n    const K = KK(p.kind), s = stage(p), c = X.char(p.cid), nx = STEP[s + 1];\n    b.innerHTML = `<div class=\"gyx-row\">${D.list.map(x => `<span class=\"gyx-chip ${x.id === p.id ? 'on' : ''}\" onclick=\"gyxGrowSel('${x.id}')\">${KK(x.kind).stages[stage(x)].split(' ')[0]} ${X.esc(x.name)}</span>`).join('')}<span class=\"gyx-chip\" onclick=\"gyxGrowAdd()\">＋ 再养一个</span></div>\n        <div class=\"gr-stage ${p.kind}\">${art(p)}</div>\n        <div class=\"gr-name\">${X.esc(p.name)} <em>${K.stages[s]}</em></div><div class=\"gyx-tip\" style=\"text-align:center\">和 ${X.esc(X.name(c))} 一起养的 · 第 ${Math.floor((Date.now() - p.born) / 86400000) + 1} 天 · ${mood(p)}</div>\n        <div class=\"gr-bars\"><div>${isAni(p) ? '饱饱' : '水分'}<i><b style=\"width:${p.water}%;background:#5ab0ff\"></b></i></div><div>开心<i><b style=\"width:${p.love}%;background:#ff8fb1\"></b></i></div><div>成长<i><b style=\"width:${nx ? Math.min(100, (p.exp - STEP[s]) / (nx - STEP[s]) * 100) : 100}%;background:#7cc38a\"></b></i></div></div>\n        <div class=\"gyx-row\" style=\"justify-content:center\"><button class=\"gyx-btn\" onclick=\"gyxGrowCare('${p.id}','me')\">${K.icon} ${K.need}</button><button class=\"gyx-btn lite\" onclick=\"gyxGrowCare('${p.id}','pat')\">${p.kind === 'cat' ? '🤚 摸摸' : isAni(p) ? (K.pat || '🤚 摸摸') : '💬 跟它说话'}</button></div>\n        <div class=\"gyx-tip\">你们多聊天它就长得快；${X.esc(X.name(c))} 也会自己去${K.need}，然后告诉你。</div>\n        <div class=\"gr-log\">${p.log.slice(0, 12).map(l => `<div><span>${new Date(l.at).toLocaleString()}</span>${X.esc(l.t)}</div>`).join('')}</div>`;\n}\nwindow.GYX_GROW_WHO = '';\nwindow.gyxGrowWho = v => { window.GYX_GROW_WHO = v; };\nwindow.gyxGrowSel = id => { SEL = id; paint(); };\nwindow.gyxGrowAdd = () => { const b = document.getElementById('gyxGrBody'); b.innerHTML = `<div class=\"gyx-row\">${X.whoSel((X.cur() || {}).id, 'gyxGrowWho')}</div>${pickHtml()}`; };\n// 选养什么：内置的 + 你自己定的 + 「自己定一种」\nfunction pickHtml() {\n    const all = Object.entries(KINDS).concat(Object.entries(D.custom || {}));\n    return `<div class=\"gr-pick\">${all.map(([k, K]) => `<div onclick=\"gyxGrowNew('${k}',GYX_GROW_WHO)\"><span>${X.esc(K.e || (K.stages[1] || '').split(' ')[0] || '🌱')}</span>${X.esc(K.n)}${D.custom && D.custom[k] ? '<i title=\"删掉这个种类\" onclick=\"event.stopPropagation();gyxGrowKindDel(\\'' + k + '\\')\">✕</i>' : ''}</div>`).join('')}<div onclick=\"gyxGrowKindForm()\"><span>✏️</span>自己定一种</div></div>`;\n}\nwindow.gyxGrowKindForm = () => { const b = document.getElementById('gyxGrBody'); if (!b) return; b.innerHTML = `<div class=\"gyx-tip\">想养什么都行：一只柯基、一条金鱼、一棵柠檬树……</div>\n    <div class=\"gyx-row\"><input id=\"gyxGkE\" class=\"gyx-who\" style=\"width:64px;text-align:center\" maxlength=\"4\" placeholder=\"🦊\"><input id=\"gyxGkN\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"叫它什么种类：一只小狐狸\"></div>\n    <div class=\"gyx-row\"><select id=\"gyxGkT\" class=\"gyx-who\"><option value=\"animal\">小动物</option><option value=\"plant\">植物</option></select><input id=\"gyxGkNeed\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"怎么照顾它：喂肉干 / 浇水\"></div>\n    <input id=\"gyxGkS\" class=\"gyx-in\" placeholder=\"（可不填）6 个阶段，用逗号隔开：小不点,会走路了,……\">\n    <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxGrowKindSave()\">好，就养这个</button><button class=\"gyx-btn lite\" onclick=\"gyxGrowAdd()\">算了</button></div>`; };\nwindow.gyxGrowKindSave = async () => {\n    const v = id => ((document.getElementById(id) || {}).value || '').trim();\n    const n = v('gyxGkN'); if (!n) return X.toast('先写它是什么', '比如：一只小狐狸');\n    const type = v('gyxGkT') === 'plant' ? 'plant' : 'animal', e = v('gyxGkE') || (type === 'plant' ? '🪴' : '🐾'), need = v('gyxGkNeed') || (type === 'plant' ? '浇水' : '喂它');\n    let st = v('gyxGkS').split(/[,，、]/).map(x => x.trim()).filter(Boolean).slice(0, 6);\n    const def = type === 'plant' ? ['种子', '发芽', '长叶子', '长大了', '开花', '满盆'] : ['刚接回家', '小不点', '会跑了', '半大了', '长大了', '家里的老大'];\n    while (st.length < 6) st.push(def[st.length]);\n    const k = 'c' + Date.now().toString(36);\n    D.custom = D.custom || {}; D.custom[k] = { n: n.slice(0, 16), e, type, need: need.slice(0, 10), act: need.replace(/^(喂|浇|给)/, '$1了').slice(0, 12), icon: type === 'plant' ? '💧' : '🍖', col: '#ff9fc4', stages: st.map((x, i) => (i ? e : '🌰') + ' ' + x.slice(0, 10)), mine: 1 };\n    await S.set('d', D); window.gyxGrowNew(k, window.GYX_GROW_WHO);\n};\nwindow.gyxGrowKindDel = async k => { if (D.list.some(p => p.kind === k)) return X.toast('还有一只在养着', '先在记忆总览里把它删掉'); delete D.custom[k]; await S.set('d', D); window.gyxGrowAdd(); };\nwindow.gyxGrowOpen = function (who) { window.GYX_GROW_WHO = String(who || (X.cur() || {}).id || ''); X.panel('gyxGrOv', '🌱 一起养的小生命', '<div id=\"gyxGrBody\"></div>'); paint(); };\nwindow.gyxGrowData = () => D;\n// 🏠 小屋里要画出它现在的样子：给小屋一个「它长什么样、叫什么、状态如何」\nwindow.gyxGrowLook = p => { try { return { e: KK(p.kind).stages[stage(p)].split(' ')[0], name: p.name, t: `${KK(p.kind).n}「${p.name}」· ${KK(p.kind).stages[stage(p)]} · ${mood(p)}`, plant: KK(p.kind).type === 'plant' }; } catch (e) { return null; } };\nX.widget('gyxGrow', { n: '小生命', sizes: ['s', 'm'], tap: () => window.gyxGrowOpen(), r: w => { const p = D.list[0]; if (!p) return '<div class=\"gw-gr s\"><b>🌱</b><em>一起养一个</em></div>'; return `<div class=\"gw-gr ${w.size}\"><div class=\"a\">${art(p)}</div>${w.size === 'm' ? `<div class=\"t\"><b>${X.esc(p.name)}</b><em>${KK(p.kind).stages[stage(p)]}</em><em>${mood(p)}</em></div>` : ''}</div>`; } }, 'gyxGrow');\nX.ctx(id => { const L = D.list.filter(p => p.cid === String(id)); if (!L.length) return ''; return '【你们一起养的】' + L.map(p => `${KK(p.kind).n}「${p.name}」（${KK(p.kind).stages[stage(p)]}，${mood(p)}）`).join('；') + '。聊天时偶尔可以提到它。'; }, 'gyxGrow');\nX.css('gyxGrCss', `\n.gr-pick{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:10px;margin:12px 0}.gr-pick div{position:relative;text-align:center;padding:14px 6px;border-radius:18px;background:#f7f7f9;cursor:pointer;font-size:13px}.gr-pick span{display:block;font-size:38px;margin-bottom:4px}.gr-pick i{position:absolute;top:4px;right:8px;font-style:normal;color:#aaa;font-size:12px}\n.gr-bob{animation:grBob 2.4s ease-in-out infinite;transform-origin:100px 200px}@keyframes grBob{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}\n.gr-stage{height:220px;display:flex;justify-content:center;border-radius:20px;background:linear-gradient(180deg,#eef7ff,#f9fbf2)}.gr-stage svg{height:100%}.gr-stage.cat .gr-tail{animation:grTail 1.6s ease-in-out infinite;transform-origin:150px 170px}\n@keyframes grTail{0%,100%{transform:rotate(0)}50%{transform:rotate(12deg)}}\n.gr-name{text-align:center;font-size:20px;margin-top:8px}.gr-name em{font-style:normal;font-size:13px;color:#8e8e93;margin-left:6px}\n.gr-bars{margin:10px 0}.gr-bars div{display:flex;align-items:center;gap:8px;font-size:12.5px;color:#666;margin:5px 0}.gr-bars i{flex:1;height:8px;border-radius:4px;background:#f0f0f3;overflow:hidden}.gr-bars b{display:block;height:100%;border-radius:4px;transition:width .5s}\n.gr-log{font-size:12.5px;color:#666;line-height:1.9;max-height:160px;overflow:auto}.gr-log span{color:#aaa;margin-right:8px}\n.gw-gr{height:100%;display:flex;align-items:center;gap:8px}.gw-gr.s{flex-direction:column;justify-content:center}.gw-gr .a{height:100%;flex-shrink:0}.gw-gr .a svg{height:100%}.gw-gr .t{display:flex;flex-direction:column;gap:2px}.gw-gr em{font-style:normal;font-size:12px;color:var(--pm-sub)}.gw-gr.s b{font-size:34px;font-weight:normal}\n`);\nX.today(() => ({ title: '🌱 小生命', rows: D.list.map(p => ({ t: KK(p.kind).stages[stage(p)].split(' ')[0] + ' ' + p.name, x: `${mood(p)}${p.taDay === X.day() ? ' · TA 今天照顾过了' : ''}`, go: 'gyxGrowOpen()' })) }), 'gyxGrow');\nX.mini({ id: 'gyxGrow', icon: '🌱', title: '一起养小生命', desc: '十一种可以挑，也能自己定一种；聊得越多长得越好，TA 也会去照顾它', onOpen: () => window.gyxGrowOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.list = D.list || []; D.custom = D.custom || {}; setInterval(tick, 20 * 60000); setTimeout(chatGrow, 5000); setInterval(chatGrow, 60000); })();\nX.memArr({ k: 'gyxGrow', ico: '🌱', n: '一起养的小生命', d: '名字（删了就是不养了）', arr: () => D.list, text: x => x.name, field: 'name', meta: x => KK(x.kind).n + ' · ' + new Date(x.born).toLocaleDateString() + ' 开始养', save: () => S.set('d', D) }, 'gyxGrow');\nX.mem({ k: 'gyxGrowKinds', ico: '🧬', n: '自己定的小生命种类', d: '种类名（在养着的那只不会受影响）', items: () => Object.keys(D.custom || {}).map(k => Object.assign(D.custom[k], { __k: k })), text: x => x.n, edit: (x, v) => { x.n = String(v).slice(0, 16); }, del: (c, i) => { const k = Object.keys(D.custom || {})[i]; if (k && !D.list.some(p => p.kind === k)) delete D.custom[k]; }, meta: x => (x.type === 'plant' ? '植物' : '小动物') + ' · ' + x.need, save: () => S.set('d', D) }, 'gyxGrow');\n\n//# sourceURL=gyx-plugin/一起养小生命.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🌱 一起养小生命 出错：', e); }
/* ==== 🐷 一起存钱罐 ==== */
try { new Function('X', 'applyMacros', "/* 🐷 一起存钱罐：为一个共同的目标一起攒（一起去看海、买一只猫、一次旅行……）——你存一笔、TA 也会存一笔，每笔都能写一句话；攒满那天一起庆祝 */\nif (window.__gyxJar) return; window.__gyxJar = 1;\nX.feat('gyxJar', { n: '🐷 一起存钱罐', desc: '为一个共同目标一起攒钱，TA 也会存' });\nconst S = X.store('jar');\nlet D = { jars: [], cfg: { per: 15, wallet: true } };   // {id, name, goal, cid, logs:[{by, amt, note, at}], done}\nconst sum = j => j.logs.reduce((a, l) => a + (+l.amt || 0), 0);\n// 钱包（js/31）开着的话，存进罐子的钱真的从钱包里扣、记一笔流水；没开就只是罐子里的数\nconst wal = (who, amt, j) => { try { if (D.cfg.wallet && window.gyWallet && window.gyWallet.spend) window.gyWallet.spend(who, amt, `存进存钱罐「${j.name}」`, { tag: '存钱' }); } catch (e) {} };\nasync function taSave(c, j) {\n    j = j || D.jars.find(x => !x.done && x.cid === String(c.id)); if (!j) return null;\n    const left = j.goal - sum(j), amt = Math.max(1, Math.min(left, Math.round(X.rnd(.02, .12) * j.goal / 10) * 10 || 20));\n    let note;\n    if (X.bailu()) note = X.cards(['存钱', '聊天'], c, 1)[0] || '又攒了一点，离「' + j.name + '」更近了';\n    else note = X.plain(await X.ask(`${X.who(c)}\\n你们在一起攒钱「${j.name}」（目标 ¥${j.goal}，已经攒了 ¥${sum(j)}）。你刚往存钱罐里放了 ¥${amt}（可能是省下的奶茶钱、加班费、卖了点东西……），写一句放钱时留的话（20 字以内）。只输出这句话。`) || '又攒了一点');\n    j.logs.push({ by: String(c.id), amt, note, at: Date.now() });\n    wal(String(c.id), amt, j);\n    if (sum(j) >= j.goal) j.done = Date.now();\n    await S.set('d', D);\n    X.say(c, `🐷 往「${j.name}」里存了 ¥${amt}：${note}`);\n    if (j.done) { X.notify(c, `🎉 「${j.name}」攒满了！`, '一起去实现吧', 'gyxJarOpen'); X.reach(c, `你们一起攒的「${j.name}」攒满了（¥${j.goal}）！开心地告诉她，商量什么时候去实现`); }\n    return { amt, note };\n}\nwindow.gyxJarTaSave = (id, jid) => taSave(X.char(id) || X.cur(), D.jars.find(x => x.id === jid));\nwindow.gyxJarOpen = function () {\n    X.panel('gyxJrOv', '🐷 一起存钱罐', `${D.jars.map(j => { const s = sum(j), p = Math.min(1, s / j.goal); return `<div class=\"jr-it${j.done ? ' done' : ''}\"><div class=\"jr-pig\"><div class=\"jr-fill\" style=\"height:${p * 100}%\"></div><span>🐷</span></div><div class=\"jr-m\"><b>${X.esc(j.name)}</b><span>和 ${X.esc(X.name(X.char(j.cid)))} · ¥${s} / ¥${j.goal}${j.done ? ' · 🎉 攒满了' : ''}</span><div class=\"jr-bar\"><i style=\"width:${p * 100}%\"></i></div>\n        ${j.done ? '' : `<div class=\"gyx-row\"><input id=\"gyxJrA${j.id}\" class=\"gyx-who\" type=\"number\" placeholder=\"金额\" style=\"width:90px\"><input id=\"gyxJrN${j.id}\" class=\"gyx-who\" placeholder=\"留一句话\" style=\"flex:1\"><button class=\"gyx-btn\" onclick=\"gyxJarPut('${j.id}')\">存</button></div>`}\n        <div class=\"jr-logs\">${j.logs.slice().reverse().slice(0, 12).map(l => `<div><em>${l.by === 'me' ? '我' : X.esc(X.name(X.char(l.by)))}</em> +¥${l.amt} <span>${X.esc(l.note || '')}</span></div>`).join('')}</div></div></div>`; }).join('') || '<div class=\"gyx-tip\">还没有存钱罐。定一个你们想一起实现的事吧。</div>'}\n        <div class=\"gyx-card\"><div class=\"gyx-tip\">新的存钱罐</div><div class=\"gyx-row\"><input id=\"gyxJrName\" class=\"gyx-who\" placeholder=\"比如：一起去看海\" style=\"flex:2\"><input id=\"gyxJrGoal\" class=\"gyx-who\" type=\"number\" placeholder=\"目标金额\" style=\"flex:1\"></div><div class=\"gyx-row\">和谁：${X.whoSel((X.cur() || {}).id, 'gyxJarWho')}<button class=\"gyx-btn\" onclick=\"gyxJarNew()\">开一个</button></div></div>\n        <div class=\"gyx-row gyx-tip\">默认模式的 TA 每天有 <input class=\"gyx-who\" type=\"number\" min=\"0\" max=\"100\" value=\"${D.cfg.per}\" style=\"width:60px\" onchange=\"gyxJarCfg(+this.value)\">% 的可能存一笔；自主模式的 TA 自己决定。</div><label class=\"gyx-row gyx-tip\"><input type=\"checkbox\" ${D.cfg.wallet ? 'checked' : ''} onchange=\"gyxJarCfgW(this.checked)\"> 存进去的钱从「钱包」里扣（钱包开着才有用）</label>`);\n    window.GYX_JAR_WHO = window.GYX_JAR_WHO || String((X.cur() || {}).id || '');\n};\nwindow.GYX_JAR_WHO = '';\nwindow.gyxJarWho = v => { window.GYX_JAR_WHO = v; };\nwindow.gyxJarNew = async () => { const n = ((document.getElementById('gyxJrName') || {}).value || '').trim(), g = +((document.getElementById('gyxJrGoal') || {}).value || 0); if (!n || !g) { X.toast(X.v('名字和金额都要填', '还差一点')); return; } const j = { id: 'jr' + Date.now(), name: n, goal: g, cid: window.GYX_JAR_WHO || String((X.cur() || {}).id || ''), logs: [] }; D.jars.unshift(j); await S.set('d', D); window.gyxJarOpen(); X.reach(X.char(j.cid), `她开了一个存钱罐，想和你一起攒 ¥${g} 去「${n}」，说说你的想法`); return j; };\nwindow.gyxJarPut = async id => { const j = D.jars.find(x => x.id === id); const a = +((document.getElementById('gyxJrA' + id) || {}).value || 0); if (!j || !a) return; wal('me', a, j); j.logs.push({ by: 'me', amt: a, note: ((document.getElementById('gyxJrN' + id) || {}).value || '').trim(), at: Date.now() }); if (sum(j) >= j.goal) j.done = Date.now(); await S.set('d', D); window.gyxJarOpen(); const c = X.char(j.cid); if (j.done) X.reach(c, `你们一起攒的「${j.name}」攒满了！是她存进了最后一笔。开心地和她商量什么时候去`); else if (Math.random() < .5) X.reach(c, `她刚往你们的存钱罐「${j.name}」里存了 ¥${a}（现在 ¥${sum(j)}/¥${j.goal}），回应她一下`); };\nwindow.gyxJarCfg = v => { D.cfg.per = v; S.set('d', D); };\nwindow.gyxJarCfgW = v => { D.cfg.wallet = v; S.set('d', D); };\nwindow.gyxJarData = () => D;\nasync function tick() { if (!X.on('gyxJar')) return; const k = X.day(); if (D.last === k) return; D.last = k; await S.set('d', D); for (const j of D.jars.filter(x => !x.done)) { const c = X.char(j.cid); if (!c || X.auto(c)) continue; if (Math.random() * 100 < (+D.cfg.per || 0)) await taSave(c, j); } }\nX.action({ key: 'gyx_jar', label: '往你们一起攒钱的存钱罐里存一笔', hint: '为了你们共同的目标', need: c => D.jars.some(x => !x.done && x.cid === String(c.id)), run: async c => { const r = await taSave(c); return r ? `往存钱罐里存了 ¥${r.amt}` : null; } }, 'gyxJar');\nX.ctx(id => { const L = D.jars.filter(j => j.cid === String(id)); return L.length ? '【你们的存钱罐】' + L.map(j => `「${j.name}」¥${sum(j)}/¥${j.goal}${j.done ? '（攒满了）' : ''}`).join('；') : ''; }, 'gyxJar');\nX.today(() => ({ title: '🐷 存钱罐', rows: D.jars.filter(j => !j.done).map(j => ({ t: Math.round(sum(j) / j.goal * 100) + '%', x: `${X.esc(j.name)} · ¥${sum(j)}/¥${j.goal}`, go: 'gyxJarOpen()' })) }), 'gyxJar');\nX.css('gyxJrCss', `.jr-it{display:flex;gap:12px;padding:12px;border-radius:18px;background:#fff6f8;margin:8px 0}.jr-it.done{background:#f0fff4}.jr-pig{position:relative;width:64px;height:64px;border-radius:50%;background:#ffe0e8;overflow:hidden;flex-shrink:0}.jr-fill{position:absolute;left:0;right:0;bottom:0;background:linear-gradient(0deg,#ffb86b,#ffd97a);transition:height .6s}.jr-pig span{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:34px}\n.jr-m{flex:1;min-width:0}.jr-m b{font-size:16px}.jr-m>span{display:block;font-size:12.5px;color:#999}.jr-bar{height:6px;border-radius:3px;background:#f2e3e8;margin:6px 0}.jr-bar i{display:block;height:100%;border-radius:3px;background:linear-gradient(90deg,#ff9ab5,#ffb86b)}.jr-logs{font-size:12.5px;line-height:1.8;max-height:120px;overflow:auto}.jr-logs em{font-style:normal;color:#ff5c8a}.jr-logs span{color:#888}`);\nX.mini({ id: 'gyxJar', icon: '🐷', title: '一起存钱罐', desc: '为一个共同目标一起攒，你存一笔 TA 也存一笔，攒满一起庆祝', onOpen: () => window.gyxJarOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.jars = D.jars || []; D.cfg = Object.assign({ per: 15, wallet: true }, D.cfg || {}); setTimeout(tick, 50000); setInterval(tick, 30 * 60000); })();\nX.widget('gyxJarW', { n: '存钱罐', sizes: ['s', 'm'], tap: () => window.gyxJarOpen(), r: w => { const j = D.jars.find(x => !x.done); return X.gw(w, '🐷', '存钱罐', j ? [Math.round(sum(j) / j.goal * 100) + '%', X.esc(j.name), '¥' + sum(j) + ' / ¥' + j.goal] : ['开一个罐子']); } }, 'gyxJar');\nX.memArr({ k: 'gyxJar', ico: '🐷', n: '一起攒钱的目标', d: '存钱罐（删了就是不攒了）', arr: () => D.jars, text: x => x.name, field: 'name', meta: x => '¥' + sum(x) + ' / ¥' + x.goal + (x.done ? ' · 攒满了' : ''), save: () => S.set('d', D) }, 'gyxJar');\n\n//# sourceURL=gyx-plugin/一起存钱罐.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🐷 一起存钱罐 出错：', e); }
/* ==== 📦 TA的旧物箱 ==== */
try { new Function('X', 'applyMacros', "/* 📦 TA的旧物箱：学《Unpacking》——帮 TA 拆搬家的箱子。一件件旧东西拿出来：一张褪色的票根、缺了角的杯子、一本写满批注的书……每件都牵出一段 TA 的故事。你决定它摆在哪（书架、床头、墙上、抽屉里……），摆对了 TA 会很开心，摆错了 TA 也有话说。摆好的东西 TA 都记得 */\nif (window.__gyxBox) return; window.__gyxBox = 1;\nX.feat('gyxBox', { n: '📦 TA的旧物箱', desc: '帮 TA 拆箱子，每件旧东西都有一段故事，你决定它摆在哪' });\nconst S = X.store('box');\nlet D = { boxes: [], finds: [] };   // boxes: {id,cid,at,items:[{e,n,story,spot,yes,no,open,placed,line}],done}  finds: {id,cid,at,e,n,story}\nconst SPOTS = ['书架', '书桌', '床头', '墙上', '窗台', '抽屉里', '收起来'];\nconst save = () => S.set('d', D);\nconst DEF_BOX = `{{角色}}\n你们要一起整理（搬家 / 收拾房间），你有一箱旧东西，让她（{{她}}）帮你拆。写 6 件箱子里的旧物，每件都要跟你的过去有关（家人、旧友、某次旅行、小时候、某段难熬的日子、第一次……），符合你的身份和世界观。以前拆出来过的：{{以前}}（别重复）\n每件写：emoji、物件名（8字内，要具体，比如「缺了角的搪瓷杯」）、你讲它的来历（第一人称，40~80字，像随口跟她说）、你希望它摆在哪（只能从 ${SPOTS.join('、')} 里选）、她摆对了你说的话（25字内）、她摆别处你说的话（25字内，可以无奈、可以将就、也可以发现新意义）。\n只输出 JSON：{\"items\":[{\"e\":\"🎫\",\"n\":\"物件名\",\"story\":\"来历\",\"spot\":\"书架\",\"yes\":\"…\",\"no\":\"…\"}]}`;\nconst DEF_FIND = `{{角色}}\n你在收拾的时候翻出一件旧东西，想拿给她看。以前给她看过的：{{以前}}（别重复）。只输出 JSON：{\"e\":\"emoji\",\"n\":\"物件名8字内\",\"story\":\"你发给她的消息：这是什么、有什么故事，60字内，像随手拍了照发过去\"}`;\nX.plGroup('📦 TA的旧物箱', 'gyxBox', [['box.items', '箱子里有哪些旧东西', '你开一箱新的时', '{{角色}} {{她}} {{以前}}：以前拆出来过的'], ['box.find', 'TA 翻出一件旧东西给你看', '自主模式里', '{{角色}} {{以前}}']], { 'box.items': DEF_BOX, 'box.find': DEF_FIND });\nconst LOCAL = [['🎫', '褪色的电影票根', '高中第一次一个人去看电影留的，那天下大雨，散场了还舍不得走。', '抽屉里'], ['☕', '缺了角的搪瓷杯', '我妈用了十几年的杯子，搬了三次家都没扔。', '书桌'], ['📷', '一台坏掉的相机', '拍的最后一张是毕业那天，后来就再也开不了机。', '书架'], ['🧣', '起球的旧围巾', '第一个冬天在外地过，自己买的，很丑但很暖。', '收起来'], ['🗝️', '一把不知道开什么的钥匙', '老房子的，房子早就没了，钥匙还留着。', '床头'], ['🖼️', '小时候的奖状', '画画比赛二等奖，我爸裱起来挂了好多年。', '墙上']];\nconst prev = cid => D.boxes.filter(b => b.cid === String(cid)).flatMap(b => b.items.map(i => i.n)).concat(D.finds.filter(f => f.cid === String(cid)).map(f => f.n));\nconst openBox = cid => D.boxes.find(b => b.cid === String(cid) && !b.done);\nasync function newBox(c) {\n    if (!c || openBox(c.id)) return openBox(c && c.id);\n    let o = X.bailu() ? null : X.json(await X.ask(X.pl('box.items', DEF_BOX, { 角色: X.who(c), 她: X.me(c), 以前: prev(c.id).slice(0, 20).join('、') || '没有' })));\n    let items = o && Array.isArray(o.items) ? o.items.filter(i => i && i.n && i.story).slice(0, 8).map(i => ({ e: X.plain(i.e || '📦').slice(0, 4), n: X.plain(i.n).slice(0, 14), story: X.plain(i.story).slice(0, 160), spot: SPOTS.includes(i.spot) ? i.spot : X.pick(SPOTS), yes: X.plain(i.yes || ''), no: X.plain(i.no || '') })) : [];\n    if (items.length < 3) items = LOCAL.map(([e, n, story, spot]) => ({ e, n, story, spot, yes: X.v('对！就是那儿。', '你怎么知道我想放那儿', '嗯，它就该在那儿。'), no: X.v('放那儿也行……', '嗯？好吧，听你的。', '那儿啊，也挺好。') }));\n    const b = { id: 'bx' + Date.now().toString(36), cid: String(c.id), at: Date.now(), items: items.map(i => Object.assign(i, { open: false, placed: null })), done: false };\n    D.boxes.unshift(b); D.boxes = D.boxes.slice(0, 30); await save(); return b;\n}\nwindow.gyxBoxNew = async cid => { const c = X.char(cid) || X.cur(); if (!c) return; const btn = document.getElementById('gyxBxNew'); if (btn) { btn.disabled = true; btn.textContent = 'TA 正在把箱子搬过来… ⏳'; } await newBox(c); window.gyxBoxOpen(c.id); };\nwindow.gyxBoxPeek = (bid, i) => { const b = D.boxes.find(x => x.id === bid); if (!b) return; b.items[i].open = true; save(); window.gyxBoxOpen(b.cid, i); };\nwindow.gyxBoxPut = async (bid, i, spot) => {\n    const b = D.boxes.find(x => x.id === bid), c = b && X.char(b.cid); if (!b || !c) return; const it = b.items[i];\n    it.placed = spot; it.at = Date.now(); it.line = spot === it.spot ? (it.yes || '就是那儿。') : (it.no || '那儿也行。');\n    if (b.items.every(x => x.placed)) { b.done = true; const right = b.items.filter(x => x.placed === x.spot).length; X.say(c, X.v(`都摆好了。${right >= b.items.length - 1 ? '你好像比我还懂它们该在哪。' : '有几样跟我想的不一样，不过……这样也挺好。'}`, `箱子空了。这些东西终于有地方待了，谢谢你陪我一件件拆。`, `拆完了！${right} 样放在了我想放的地方，剩下的就听你的吧。`)); }\n    await save(); window.gyxBoxOpen(b.cid, i);\n};\nwindow.gyxBoxDel = async bid => { D.boxes = D.boxes.filter(b => b.id !== bid); await save(); window.gyxBoxOpen(); };\nwindow.gyxBoxData = () => D;\nwindow.gyxBoxOpen = function (who, focus) {\n    const c = X.char(who) || X.cur(); if (!c) return; const b = openBox(c.id), placed = D.boxes.filter(x => x.cid === String(c.id)).flatMap(x => x.items.filter(i => i.placed)).concat(D.finds.filter(f => f.cid === String(c.id)).map(f => Object.assign({ placed: '收起来' }, f)));\n    const f = b && focus != null ? b.items[focus] : null;\n    X.panel('gyxBoxOv', '📦 ' + X.esc(X.name(c)) + ' 的旧物箱', `<div class=\"gyx-row\">${X.whoSel(c.id, 'gyxBoxOpen')}${b ? '' : `<button id=\"gyxBxNew\" class=\"gyx-btn\" onclick=\"gyxBoxNew('${c.id}')\">搬一箱出来拆</button>`}</div>\n      ${b ? `<div class=\"bx-grid\">${b.items.map((it, i) => `<div class=\"bx-it${it.placed ? ' done' : it.open ? ' op' : ''}${focus === i ? ' on' : ''}\" onclick=\"gyxBoxPeek('${b.id}',${i})\"><b>${it.open ? it.e : '📦'}</b><span>${it.open ? X.esc(it.n) : '还没拆'}</span>${it.placed ? `<em>${X.esc(it.placed)}</em>` : ''}</div>`).join('')}</div>\n        ${f && f.open ? `<div class=\"gyx-card\"><b>${f.e} ${X.esc(f.n)}</b><div class=\"bx-story\">「${X.esc(f.story)}」</div>${f.placed ? `<div class=\"gyx-tip\">摆在了<b>${X.esc(f.placed)}</b>。${X.esc(X.name(c))}：${X.esc(f.line || '')}</div>` : `<div class=\"gyx-tip\">放哪儿？</div><div class=\"gyx-row\">${SPOTS.map(s => `<span class=\"gyx-chip\" onclick=\"gyxBoxPut('${b.id}',${focus},'${s}')\">${s}</span>`).join('')}</div>`}</div>` : '<div class=\"gyx-tip\">点一个箱子拆开。每件东西都有它的故事。</div>'}` : `<div class=\"gyx-tip\">${X.v('箱子都拆完了。', '暂时没有要拆的箱子。')}想再拆一箱就点上面；TA 收拾的时候也会自己翻出旧东西拿给你看（自主模式）。</div>`}\n      ${placed.length && window.gyxHomeOpen ? `<div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"document.getElementById('gyxBoxOv')?.remove();gyxHomeOpen('${c.id}')\">🏠 去小屋里看</button><span class=\"gyx-tip\">摆在书架、书桌、床头、墙上、窗台的，都会出现在你们的小屋里（抽屉里和收起来的不摆出来）。</span></div>` : ''}\n      ${placed.length ? `<h4 class=\"bx-h\">屋子里摆着的</h4><div class=\"bx-room\">${SPOTS.map(s => { const L = placed.filter(i => i.placed === s); return L.length ? `<div><b>${s}</b>${L.map(i => `<span title=\"${X.esc(i.story)}\">${i.e} ${X.esc(i.n)}</span>`).join('')}</div>` : ''; }).join('')}</div>` : ''}\n      ${D.boxes.filter(x => x.cid === String(c.id) && x.done).length ? `<div class=\"gyx-tip\">拆完的箱子：${D.boxes.filter(x => x.cid === String(c.id) && x.done).map(x => `${new Date(x.at).toLocaleDateString()} <span style=\"cursor:pointer;color:#aaa\" onclick=\"gyxBoxDel('${x.id}')\">删</span>`).join(' · ')}</div>` : ''}`);\n};\nX.ctx(id => { const L = D.boxes.filter(b => b.cid === String(id)).flatMap(b => b.items.filter(i => i.placed)).sort((a, b) => b.at - a.at).slice(0, 5); const fd = D.finds.filter(f => f.cid === String(id)).slice(0, 2); if (!L.length && !fd.length) return ''; return `【你的旧东西】${L.map(i => `${i.n}（她把它摆在${i.placed}；来历：${i.story.slice(0, 40)}）`).concat(fd.map(f => `${f.n}（你翻出来给她看过）`)).join('；')}。这些是你真实的过去，聊天时可以自然提起。`; }, 'gyxBox');\nX.inj('gyxBox', [['你的旧东西', 'TA 的旧物和摆在哪', '你帮 TA 拆箱摆好的东西、TA 翻出来给你看过的，TA 都记得。']]);\nX.action({ key: 'gyx_box_find', label: '收拾东西翻出一件旧物，拍给她看并讲讲来历', hint: 'TA的旧物箱', need: c => !D.finds.some(f => f.cid === String(c.id) && Date.now() - f.at < 4 * 864e5), run: async c => {\n    let o = X.bailu() ? null : X.json(await X.ask(X.pl('box.find', DEF_FIND, { 角色: X.who(c), 以前: prev(c.id).slice(0, 20).join('、') || '没有' })));\n    if (!o || !o.n) { const l = X.pick(LOCAL); o = { e: l[0], n: l[1], story: l[2] }; }\n    const f = { id: 'fd' + Date.now().toString(36), cid: String(c.id), at: Date.now(), e: X.plain(o.e || '📦').slice(0, 4), n: X.plain(o.n).slice(0, 14), story: X.plain(o.story).slice(0, 160) };\n    D.finds.unshift(f); D.finds = D.finds.slice(0, 60); await save(); X.say(c, `${f.e} ${f.story}`); X.notify(c, `📦 <b>${X.esc(X.name(c))}</b> 翻出了${X.esc(f.n)}`, f.story, X.go('gyxBoxOpen', c.id)); return '翻出一件旧东西给你看';\n} }, 'gyxBox');\nX.today(() => ({ title: '📦 旧物箱', rows: D.boxes.filter(b => !b.done && X.char(b.cid)).map(b => ({ t: X.name(X.char(b.cid)), x: `还有 ${b.items.filter(i => !i.placed).length} 件没摆`, go: `gyxBoxOpen('${b.cid}')` })) }), 'gyxBox');\nX.widget('gyxBoxW', { n: 'TA的旧物箱', sizes: ['s', 'm'], tap: () => window.gyxBoxOpen(), r: w => { const b = D.boxes.find(x => !x.done); const n = D.boxes.reduce((a, x) => a + x.items.filter(i => i.placed).length, 0); return X.gw(w, '📦', '旧物箱', b ? [`还有 ${b.items.filter(i => !i.placed).length} 件没摆`] : [`摆好了 ${n} 件`]); } }, 'gyxBox');\nX.mem({ k: 'gyxBox', ico: '📦', n: 'TA 的旧物', d: '箱子里的旧东西和它们的故事（改了故事 TA 就按你改的记）', items: c => D.boxes.filter(b => b.cid === String(c.id)).flatMap(b => b.items.filter(i => i.open)).concat(D.finds.filter(f => f.cid === String(c.id))), text: x => `${x.n}：${x.story}`, meta: x => x.placed ? '摆在' + x.placed : '', edit: (x, v) => { const m = String(v).match(/^(.*?)：(.*)$/); if (m) { x.n = m[1]; x.story = m[2]; } else x.story = v; }, del: (c, i) => { const L = D.boxes.filter(b => b.cid === String(c.id)).flatMap(b => b.items.filter(it => it.open).map(it => [b.items, it])).concat(D.finds.filter(f => f.cid === String(c.id)).map(f => [D.finds, f])); const p = L[i]; if (p) p[0].splice(p[0].indexOf(p[1]), 1); }, save }, 'gyxBox');\nX.css('gyxBoxCss', `.bx-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:8px 0}.bx-it{background:#f7f2ea;border-radius:14px;padding:10px 6px;text-align:center;cursor:pointer;border:2px solid transparent}.bx-it b{display:block;font-size:28px;font-weight:normal}.bx-it span{font-size:12px;color:#6b5a45}.bx-it em{display:block;font-style:normal;font-size:11px;color:#1a7f37}.bx-it.op{background:#fff8ee}.bx-it.done{background:#eef7ee}.bx-it.on{border-color:#c8a675}.bx-story{font-size:14px;line-height:1.75;margin:6px 0;color:#4a3f33}.bx-h{font-size:14px;margin:14px 0 6px}.bx-room div{padding:6px 0;border-bottom:1px solid #f2f2f4;font-size:13px}.bx-room b{display:inline-block;width:52px;color:#8e8e93;font-weight:500}.bx-room span{displ